// Golden generated by freshclaim/fresh-claim at 7f64d735e124eea3195cfd43950e3af877fc03a3.
// Command in that checkout (sidecars changed only to fc-proof-capture/2):
// node ./scripts/fc-proof-media-fetch.mjs --merge-local mobile=<tmp>/mobile admin=<tmp>/admin dashboard=<tmp>/dashboard pdf=<tmp>/pdf --head aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa --out <tmp>/out
import assert from 'node:assert/strict'
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import test from 'node:test'
import { fileURLToPath } from 'node:url'
import {
  fetchProofMedia,
  mediaHookMain,
  mediaSources,
  mergeArtifacts,
  mergeLocalMain,
  readBaseConfig,
} from './verify-ci-media.mjs'

const FIXTURES = new URL('./testdata/ci-media/', import.meta.url)
const read = (name) => JSON.parse(fs.readFileSync(new URL(name, FIXTURES), 'utf8'))
const CONFIG = read('sources.json')
const SOURCES = mediaSources(CONFIG)
const HEAD = 'a'.repeat(40)
const BASE = 'b'.repeat(40)
const EXPECTED = read('expected-manifest.json')
const FILES = read('expected-files.json')

function temporary(t) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ci-media-parity-'))
  t.after(() => fs.rmSync(dir, { recursive: true, force: true, maxRetries: 3 }))
  return dir
}

function staged(dir) {
  return fs
    .readdirSync(dir, { recursive: true })
    .filter((file) => fs.statSync(path.join(dir, file)).isFile())
    .sort()
}

test('FreshClaim parity: configured sources merge to the reference manifest and staged files', (t) => {
  const evidenceDir = temporary(t)
  const dirs = Object.fromEntries(
    SOURCES.map(({ suite }) => [suite, fileURLToPath(new URL(suite + '/', FIXTURES))]),
  )
  assert.deepEqual(mergeArtifacts({ dirs, evidenceDir, head: HEAD, sources: SOURCES }), EXPECTED)
  assert.deepEqual(staged(evidenceDir), FILES)
  for (const file of FILES) {
    assert.deepEqual(
      fs.readFileSync(path.join(evidenceDir, file)),
      fs.readFileSync(new URL(file, FIXTURES)),
    )
  }
})

test('FreshClaim parity: fetching the four configured CI sources matches the reference', (t) => {
  const evidenceDir = temporary(t)
  const workflows = [...new Set(SOURCES.map((source) => source.workflow))]
  const gh = (args) => {
    if (args[0] === 'run') {
      const source = SOURCES.find(
        (source) => source.artifact.replaceAll('{head}', HEAD) === args[6],
      )
      assert.ok(source)
      fs.cpSync(new URL(source.suite + '/', FIXTURES), args[8], { recursive: true })
      return { status: 0, stdout: '' }
    }
    const url = new URL(args[1], 'https://api.github.com/')
    const workflow = workflows.find((name) => url.pathname.includes('/workflows/' + name + '/runs'))
    if (workflow)
      return {
        status: 0,
        stdout: JSON.stringify({
          workflow_runs: [{ id: workflows.indexOf(workflow) + 100, head_sha: HEAD }],
        }),
      }
    const runId = Number(url.pathname.match(/\/runs\/(\d+)\//)?.[1])
    const sources = SOURCES.filter((source) => source.workflow === workflows[runId - 100])
    if (url.pathname.endsWith('/jobs'))
      return {
        status: 0,
        stdout: JSON.stringify({
          jobs: sources.map((source) => ({
            name: source.job,
            status: 'completed',
            conclusion: 'success',
            started_at: '2026-11-10T00:00:00Z',
          })),
        }),
      }
    assert.ok(url.pathname.endsWith('/artifacts'))
    return {
      status: 0,
      stdout: JSON.stringify({
        artifacts: sources.map((source) => ({
          name: source.artifact.replaceAll('{head}', HEAD),
          expired: false,
          created_at: '2026-11-10T00:05:00Z',
        })),
      }),
    }
  }
  assert.deepEqual(
    fetchProofMedia(
      { repo: 'example/project', pr: 12, headSha: HEAD, evidenceDir },
      { sources: SOURCES, gh },
    ),
    EXPECTED,
  )
  assert.deepEqual(staged(evidenceDir), FILES)
})

test('media sources are absent by default and duplicate suites fail', () => {
  assert.deepEqual(mediaSources({}), [])
  assert.throws(
    () => mediaSources({ proofDefaults: { media: { sources: [SOURCES[0], SOURCES[0]] } } }),
    /duplicate/,
  )
})

test('an unavailable constructor suite does not discard a successful source', (t) => {
  const mobile = SOURCES[0]
  const sources = [mobile, { ...mobile, suite: 'constructor', job: 'failed-capture' }]
  const evidenceDir = temporary(t)
  const gh = (args) => {
    if (args[0] === 'run') {
      fs.cpSync(new URL('mobile/', FIXTURES), args[8], { recursive: true })
      return { status: 0, stdout: '' }
    }
    const url = new URL(args[1], 'https://api.github.com/')
    if (url.pathname.endsWith('/runs'))
      return {
        status: 0,
        stdout: JSON.stringify({ workflow_runs: [{ id: 100, head_sha: HEAD }] }),
      }
    if (url.pathname.endsWith('/jobs'))
      return {
        status: 0,
        stdout: JSON.stringify({
          jobs: sources.map((source) => ({
            name: source.job,
            status: 'completed',
            conclusion: source.suite === 'constructor' ? 'failure' : 'success',
            started_at: '2026-11-10T00:00:00Z',
          })),
        }),
      }
    assert.ok(url.pathname.endsWith('/artifacts'))
    return {
      status: 0,
      stdout: JSON.stringify({
        artifacts: [
          {
            name: mobile.artifact.replaceAll('{head}', HEAD),
            expired: false,
            created_at: '2026-11-10T00:05:00Z',
          },
        ],
      }),
    }
  }
  const manifest = fetchProofMedia(
    { repo: 'example/project', pr: 12, headSha: HEAD, evidenceDir },
    { sources, gh },
  )
  assert.deepEqual(
    manifest.clips.map(({ id }) => id),
    ['mobile-proof', 'mobile-plain'],
  )
  assert.ok(staged(evidenceDir).every((file) => file.startsWith('mobile/')))
})

test('base config is read from baseSha and unrelated deferred stages do not prevent sources', () => {
  let seen
  const config = readBaseConfig({
    baseSha: BASE,
    cwd: '/checkout',
    run: (command, args, options) => {
      seen = { command, args, cwd: options.cwd }
      return {
        status: 0,
        stdout: JSON.stringify({ ...CONFIG, verifyDefaults: { admission: false } }),
      }
    },
  })
  assert.deepEqual(seen, {
    command: 'git',
    args: ['show', BASE + ':.boss-skills.json'],
    cwd: '/checkout',
  })
  assert.deepEqual(mediaSources(config), SOURCES)
})

test('partial base config keeps configured sources and receives defaults', () => {
  const config = readBaseConfig({
    baseSha: BASE,
    run: () => ({ status: 0, stdout: JSON.stringify(CONFIG) }),
  })
  assert.deepEqual(mediaSources(config), SOURCES)
  assert.ok(Array.isArray(config.env.headlessSignals))
})

test('hook reads a partial source config without requiring default-filled blocks', (t) => {
  let stdout = ''
  let calls = 0
  const code = mediaHookMain({
    stdinText: JSON.stringify({
      role: 'proof-media',
      repo: 'example/project',
      pr: 12,
      headSha: HEAD,
      baseSha: BASE,
      evidenceDir: temporary(t),
    }),
    run: () => ({ status: 0, stdout: JSON.stringify(CONFIG) }),
    gh: () => {
      calls++
      return { status: 0, stdout: JSON.stringify({ workflow_runs: [] }) }
    },
    write: (text) => {
      stdout += text
    },
    log: () => {},
  })
  assert.equal(code, 0)
  assert.equal(calls, new Set(SOURCES.map(({ workflow }) => workflow)).size)
  assert.deepEqual(JSON.parse(stdout), {
    clips: [],
    head: HEAD,
    schema: 'proof-media/1',
    transcripts: [],
  })
})

test('local merge accepts the raw configured-source fixture', (t) => {
  const evidenceDir = temporary(t)
  let stdout = ''
  const code = mergeLocalMain(
    [
      '--merge-local',
      ...SOURCES.map(({ suite }) => `${suite}=${fileURLToPath(new URL(suite + '/', FIXTURES))}`),
      '--head',
      HEAD,
      '--out',
      evidenceDir,
      '--config',
      fileURLToPath(new URL('sources.json', FIXTURES)),
    ],
    {
      write: (text) => {
        stdout += text
      },
      log: () => {},
    },
  )
  assert.equal(code, 0)
  assert.deepEqual(JSON.parse(stdout), EXPECTED)
  assert.deepEqual(staged(evidenceDir), [...FILES, 'proof-media.json'].sort())
})

test('missing base config gives no sources, while git and config faults fail', () => {
  assert.deepEqual(
    readBaseConfig({
      baseSha: BASE,
      run: () => ({
        status: 128,
        stderr: "fatal: path '.boss-skills.json' does not exist in 'base'",
      }),
    }),
    {},
  )
  for (const result of [
    { status: 1 },
    { status: 0, stdout: '{' },
    { status: 0, stdout: 'null' },
    { error: new Error('failed') },
  ]) {
    assert.throws(() => readBaseConfig({ baseSha: BASE, run: () => result }))
  }
  const config = readBaseConfig({
    baseSha: BASE,
    run: () => ({
      status: 0,
      stdout: JSON.stringify({ ...CONFIG, proofDefaults: { media: { sources: [false] } } }),
    }),
  })
  assert.throws(() => mediaSources(config), /proofDefaults/)
})

test('missing base config remains unconfigured with a non-English inherited Git locale', () => {
  const config = readBaseConfig({
    baseSha: BASE,
    run: (_command, _args, options) => ({
      status: 128,
      stderr:
        options.env?.LC_ALL === 'C'
          ? "fatal: path '.boss-skills.json' does not exist in 'base'"
          : "fatal: Pfad '.boss-skills.json' existiert nicht in 'base'",
    }),
  })
  assert.deepEqual(mediaSources(config), [])
})

test('hook exits 10 with empty stdout when base config has no sources', (t) => {
  let stdout = ''
  const code = mediaHookMain({
    stdinText: JSON.stringify({
      role: 'proof-media',
      repo: 'example/project',
      pr: 12,
      headSha: HEAD,
      baseSha: BASE,
      evidenceDir: temporary(t),
    }),
    run: () => ({ status: 0, stdout: '{}' }),
    gh: () => assert.fail('no gh call when unconfigured'),
    write: (text) => {
      stdout += text
    },
  })
  assert.equal(code, 10)
  assert.equal(stdout, '')
})

test('hook rejects missing baseSha and unreadable config with no gh calls or stdout', (t) => {
  const envelope = {
    role: 'proof-media',
    repo: 'example/project',
    pr: 12,
    headSha: HEAD,
    baseSha: BASE,
    evidenceDir: temporary(t),
  }
  for (const input of [{ ...envelope, baseSha: undefined }, envelope]) {
    let stdout = ''
    const code = mediaHookMain({
      stdinText: JSON.stringify(input),
      run: () => ({ status: 1 }),
      gh: () => assert.fail('no gh call'),
      write: (text) => {
        stdout += text
      },
      log: () => {},
    })
    assert.equal(code, 1)
    assert.equal(stdout, '')
  }
})
